 {screen==='routine'&&<><div className={`routine-banner ${categories.find(c=>c.name===routine)?.color}`}><span>{categories.find(c=>c.name===routine)?.icon}</span><div><h2>{routine}</h2><p>{daily.filter(q=>q.category===routine&&q.status==='completed').length}/{daily.filter(q=>q.category===routine).length} Completed</p></div></div><div className="quest-list">{daily.filter(q=>q.category===routine).map(questRow)}</div>{!daily.some(q=>q.category===routine)&&<Empty title="A little room for adventure" body="Your Guildmaster can add a quest here."/>}{daily.some(q=>q.category===routine&&q.timer)&&<section className="timer-card"><div className="timer-label"><span>🪥</span><div><h3>Defeat the Sugar Bugs!</h3><p>Brush, sparkle, smile.</p></div></div><div className="timer-ring" style={{background:`conic-gradient(#0085ff ${((120-seconds)/120)*360}deg,#c9e8ff 0deg)`}}><div><strong>{String(Math.floor(seconds/60)).padStart(2,'0')}:{String(seconds%60).padStart(2,'0')}</strong><small>{seconds===0?'Sparkling smile!':running?'Keep brushing!':'You’ve got this!'}</small></div></div>{seconds>0?<Button onClick={()=>{setTimerQuest(daily.find(q=>q.category===routine&&q.timer)?.id||'teeth');if(!running)deadline.current=Date.now()+seconds*1000;setRunning(!running)}}>{running?<Pause size={18}/>:<Play size={18}/>} {running?'Pause':seconds===120?'Start brushing':'Keep going'}</Button>:<Button disabled={!state.quests.some(q=>q.id===(timerQuest||daily.find(x=>x.category===routine&&x.timer)?.id)&&['active','touchup'].includes(q.status))} onClick={()=>{const q=state.quests.find(q=>q.id===(timerQuest||daily.find(x=>x.category===routine&&x.timer)?.id));if(!q)return;if(photoMode(q)!=='optional'){setSelected(q);go('photo');}else void submit(q);}}>Submit Quest <Check size={18}/></Button>}<p className="caption">Two minutes for your superhero smile.</p></section>}{routine==='Bedtime Wind-Down'&&<section className="card"><h3>🌙 Time to wind down</h3><p>Tonight’s curfew: {state.schedule[mode()].curfew}</p><p>Your next morning starts at {state.schedule[mode()].departure}.</p></section>}</>}
 {screen==='quests'&&<><div className="pills">{['All','Active','Waiting Check','Completed'].map(f=><button key={f} className={filter===f?'active':''} onClick={()=>setFilter(f)}>{f}</button>)}</div><div className="section-heading"><h2>Your quest board</h2><span>{daily.length} adventures</span></div><div className="quest-list">{daily.filter(q=>filter==='All'||filter==='Active'&&['active','touchup'].includes(q.status)||filter==='Waiting Check'&&q.status==='waiting'||filter==='Completed'&&q.status==='completed').map(questRow)}</div>{!daily.some(q=>filter==='All'||filter==='Active'&&['active','touchup'].includes(q.status)||filter==='Waiting Check'&&q.status==='waiting'||filter==='Completed'&&q.status==='completed')&&<Empty title={filter==='Completed'?'Your first win is waiting!':'All clear here!'} body="Your next adventure is on the All tab."/>}{remoteMode&&<button className="review-banner" onClick={()=>go('leaderboard')}><Star/><div><strong>Family leaderboard</strong><small>See how you rank this week</small></div><ChevronRight/></button>}{remoteMode&&<button className="review-banner" onClick={()=>go('league')}><ShieldCheck/><div><strong>{translate("Weekly league")}</strong><small>Compete with kids your age</small></div><ChevronRight/></button>}{remoteMode&&<button className="review-banner" onClick={()=>go('challenges')}><Trophy/><div><strong>{translate("Family challenges")}</strong><small>Race another family this week</small></div><ChevronRight/></button>}<div className="encouragement">✨ Every little effort is a big step forward.</div></>}
